#!/usr/bin/env python3
"""
自动生成Systolic Array Verilog Testbench
使用Golden Model生成的测试向量
"""

import json
import os

def generate_ws_testbench(tests: list, output_file: str):
    """生成WS架构的完整testbench"""

    testbench_header = '''//==============================================================================
// Auto-Generated WS Testbench with Golden Model Verification
// Generated by: generate_testbench.py
// Total Tests: ''' + str(len(tests)) + '''
//==============================================================================

`timescale 1ns/1ps

module systolic_array_ws_auto_tb;

    parameter DATA_WIDTH = 16;
    parameter WEIGHT_WIDTH = 16;
    parameter ACC_WIDTH = 32;
    parameter ARRAY_SIZE = 4;
    parameter CLK_PERIOD = 10;

    reg clk;
    reg rst_n;

    // 输入数据接口
    reg [DATA_WIDTH-1:0] input_in;
    reg input_valid;
    wire input_ready;

    // 权重数据接口
    reg [WEIGHT_WIDTH-1:0] weight_in;
    reg weight_valid;
    wire weight_ready;

    // 输出数据接口
    reg output_read;
    wire [ACC_WIDTH*ARRAY_SIZE-1:0] output_data;
    wire [ARRAY_SIZE-1:0] output_valid;

    // 控制信号
    reg weight_load;
    wire busy;

    // DUT
    systolic_array_4x4 #(
        .DATA_WIDTH(DATA_WIDTH),
        .WEIGHT_WIDTH(WEIGHT_WIDTH),
        .ACC_WIDTH(ACC_WIDTH)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .input_in(input_in),
        .input_valid(input_valid),
        .input_ready(input_ready),
        .weight_in(weight_in),
        .weight_valid(weight_valid),
        .weight_ready(weight_ready),
        .output_read(output_read),
        .output_data(output_data),
        .output_valid(output_valid),
        .weight_load(weight_load),
        .busy(busy)
    );

    // 时钟
    initial begin
        clk = 0;
        forever #(CLK_PERIOD/2) clk = ~clk;
    end

    // 测试统计
    integer total_tests = ''' + str(len(tests)) + ''';
    integer passed_tests = 0;
    integer failed_tests = 0;

    // 主测试流程
    initial begin
        $display("========================================");
        $display("WS Auto-Generated Testbench");
        $display("Total Tests: %0d", ''' + str(len(tests)) + ''');
        $display("========================================");

'''

    test_body = ""
    for idx, test in enumerate(tests, 1):
        test_name = test['name']
        description = test['description']
        input_flat = [item for row in test['input'] for item in row]
        weight_flat = [item for row in test['weight'] for item in row]
        expected_flat = [item for row in test['expected_ws'] for item in row]

        test_body += f'''
        // Test {idx}: {test_name}
        $display("\\n========================================");
        $display("Test {idx}: {test_name}");
        $display("Description: {description}");
        $display("========================================");

        // 复位
        rst_n = 0;
        input_in = 0;
        input_valid = 0;
        weight_in = 0;
        weight_valid = 0;
        weight_load = 0;
        output_read = 0;

        repeat(5) @(posedge clk);
        rst_n = 1;
        repeat(2) @(posedge clk);

        // 加载权重
        $display("\\nLoading weights...");
        weight_load = 1;
        weight_valid = 1;
'''

        # 添加权重加载
        for i, w in enumerate(weight_flat):
            test_body += f"        @(posedge clk); weight_in = 16'd{w};\n"

        test_body += '''
        weight_valid = 0;
        weight_load = 0;
        repeat(5) @(posedge clk);

        // 发送输入
        $display("\\nSending inputs...");
        input_valid = 1;
        output_read = 1;
'''

        # 添加输入数据
        for i, inp in enumerate(input_flat):
            test_body += f"        @(posedge clk); input_in = 16'd{inp};\n"

        test_body += '''
        input_valid = 0;

        // 等待输出
        fork
            begin
                wait(output_valid == 4'b1111);
            end
            begin
                repeat(1000) @(posedge clk);
            end
        join_any

        repeat(10) @(posedge clk);

        // 验证输出
        $display("\\nVerification:");
'''

        # 添加验证逻辑
        for i in range(16):
            test_body += f"        if (output_data[{i}*ACC_WIDTH +: ACC_WIDTH] == 32'd{expected_flat[i]}) begin\n"
            test_body += f"            $display(\"  ✅ PASS: output[%0d] = %0d\", {i}, $signed(output_data[{i}*ACC_WIDTH +: ACC_WIDTH]));\n"
            test_body += f"        end else begin\n"
            test_body += f"            $display(\"  ❌ FAIL: output[%0d] = %0d (expected {expected_flat[i]})\", {i}, $signed(output_data[{i}*ACC_WIDTH +: ACC_WIDTH]));\n"
            test_body += f"        end\n"

        test_body += '''
        // 统计
        begin
            integer all_match;
            integer i;
            all_match = 1'b1;
            for (i = 0; i < 16; i = i + 1) begin
                if (output_data[i*ACC_WIDTH +: ACC_WIDTH] != ''' + f"32'd{expected_flat[i]}" + ''') begin
                    all_match = 1'b0;
                end
            end
            if (all_match) begin
                passed_tests = passed_tests + 1;
                $display("\\n✅ TEST ''' + str(idx) + ''' PASSED");
            end else begin
                failed_tests = failed_tests + 1;
                $display("\\n❌ TEST ''' + str(idx) + ''' FAILED");
            end
        end

        repeat(10) @(posedge clk);
'''

    testbench_footer = '''
        // 最终报告
        $display("\\n========================================");
        $display("Final Report");
        $display("========================================");
        $display("Total Tests: %0d", total_tests);
        $display("Passed:      %0d", passed_tests);
        $display("Failed:      %0d", failed_tests);

        if (failed_tests == 0) begin
            $display("\\n✅✅✅ ALL TESTS PASSED! ✅✅✅");
        end else begin
            $display("\\n⚠️  Some tests failed");
        end
        $display("========================================\\n");

        $finish;
    end

endmodule
'''

    with open(output_file, 'w') as f:
        f.write(testbench_header)
        f.write(test_body)
        f.write(testbench_footer)


