def generate_os_testbench(tests: list, output_file: str):
    """生成OS架构的完整testbench"""

    testbench_header = '''//==============================================================================
// Auto-Generated OS Testbench with Golden Model Verification
// Generated by: generate_testbench.py
// Total Tests: ''' + str(len(tests)) + '''
//==============================================================================

`timescale 1ns/1ps

module systolic_array_os_auto_tb;

    parameter DATA_WIDTH = 16;
    parameter WEIGHT_WIDTH = 16;
    parameter ACC_WIDTH = 32;
    parameter CLK_PERIOD = 10;

    reg clk;
    reg rst_n;

    // 输入数据接口（向量输入，每列独立）
    reg [DATA_WIDTH*4-1:0] input_in;
    reg [3:0] input_valid;
    wire [3:0] input_ready;

    // 权重数据接口
    reg [WEIGHT_WIDTH-1:0] weight_in;
    reg weight_valid;
    wire weight_ready;

    // 输出数据接口
    reg output_read;
    wire [ACC_WIDTH*16-1:0] output_data;
    wire [15:0] output_valid;

    // 控制信号
    reg accumulator_clr;
    reg flush;
    reg clk_enable;
    wire busy;

    // DUT
    systolic_array_os_4x4 #(
        .DATA_WIDTH(DATA_WIDTH),
        .WEIGHT_WIDTH(WEIGHT_WIDTH),
        .ACC_WIDTH(ACC_WIDTH)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .input_in(input_in),
        .input_valid(input_valid),
        .input_ready(input_ready),
        .weight_in(weight_in),
        .weight_valid(weight_valid),
        .weight_ready(weight_ready),
        .output_read(output_read),
        .output_data(output_data),
        .output_valid(output_valid),
        .accumulator_clr(accumulator_clr),
        .flush(flush),
        .clk_enable(clk_enable),
        .busy(busy)
    );

    // 时钟
    initial begin
        clk = 0;
        forever #(CLK_PERIOD/2) clk = ~clk;
    end

    // 测试统计
    integer total_tests = ''' + str(len(tests)) + ''';
    integer passed_tests = 0;
    integer failed_tests = 0;

    // 主测试流程
    initial begin
        $display("========================================");
        $display("OS Auto-Generated Testbench");
        $display("Total Tests: %0d", ''' + str(len(tests)) + ''');
        $display("========================================");

'''

    test_body = ""
    for idx, test in enumerate(tests, 1):
        test_name = test['name']
        description = test['description']
        input_flat = [item for row in test['input'] for item in row]
        weight_flat = [item for row in test['weight'] for item in row]
        expected_flat = [item for row in test['expected_os'] for item in row]

        test_body += f'''
        // Test {idx}: {test_name}
        $display("\\n========================================");
        $display("Test {idx}: {test_name}");
        $display("Description: {description}");
        $display("========================================");

        // 复位
        rst_n = 0;
        input_in = 0;
        input_valid = 4'b0000;
        weight_in = 0;
        weight_valid = 0;
        output_read = 0;
        accumulator_clr = 0;
        flush = 0;
        clk_enable = 1;

        repeat(5) @(posedge clk);
        rst_n = 1;
        repeat(2) @(posedge clk);

        // 清除累加器
        accumulator_clr = 1;
        repeat(2) @(posedge clk);
        accumulator_clr = 0;
        repeat(5) @(posedge clk);

        // 发送输入和权重
        $display("\\nStreaming inputs and weights...");
'''

        # 添加4次输入和权重（OS需要流式发送）
        for cycle in range(4):
            # 构建向量输入（每列独立）- 每周期发送一行数据到4列
            row_idx = cycle
            col0 = input_flat[row_idx * 4 + 0]
            col1 = input_flat[row_idx * 4 + 1]
            col2 = input_flat[row_idx * 4 + 2]
            col3 = input_flat[row_idx * 4 + 3]
            w = weight_flat[cycle]

            test_body += f"        @(posedge clk);\n"
            test_body += f"        input_in = {{16'd{col3}, 16'd{col2}, 16'd{col1}, 16'd{col0}}};\n"
            test_body += f"        input_valid = 4'b1111;\n"
            test_body += f"        weight_in = 16'd{w};\n"
            test_body += f"        weight_valid = 1'b1;\n"

        test_body += '''
        input_valid = 4'b0000;
        weight_valid = 0;

        // 等待计算完成
        repeat(100) @(posedge clk);

        // 读取输出
        output_read = 1;
        repeat(5) @(posedge clk);
        output_read = 0;

        // 验证输出
        $display("\\nVerification:");
'''

        # 添加验证逻辑
        for i in range(16):
            test_body += f"        if (output_data[{i}*ACC_WIDTH +: ACC_WIDTH] == 32'd{expected_flat[i]}) begin\n"
            test_body += f"            $display(\"  ✅ PASS: output[%0d][%0d] = %0d\", {i//4}, {i%4}, $signed(output_data[{i}*ACC_WIDTH +: ACC_WIDTH]));\n"
            test_body += f"        end else begin\n"
            test_body += f"            $display(\"  ❌ FAIL: output[%0d][%0d] = %0d (expected {expected_flat[i]})\", {i//4}, {i%4}, $signed(output_data[{i}*ACC_WIDTH +: ACC_WIDTH]));\n"
            test_body += f"        end\n"

        test_body += '''
        // 统计
        begin
            integer all_match;
            integer i;
            all_match = 1'b1;
            for (i = 0; i < 16; i = i + 1) begin
                if (output_data[i*ACC_WIDTH +: ACC_WIDTH] != ''' + f"32'd{expected_flat[i]}" + ''') begin
                    all_match = 1'b0;
                end
            end
            if (all_match) begin
                passed_tests = passed_tests + 1;
                $display("\\n✅ TEST ''' + str(idx) + ''' PASSED");
            end else begin
                failed_tests = failed_tests + 1;
                $display("\\n❌ TEST ''' + str(idx) + ''' FAILED");
            end
        end

        repeat(10) @(posedge clk);
'''

    testbench_footer = '''
        // 最终报告
        $display("\\n========================================");
        $display("Final Report");
        $display("========================================");
        $display("Total Tests: %0d", total_tests);
        $display("Passed:      %0d", passed_tests);
        $display("Failed:      %0d", failed_tests);

        if (failed_tests == 0) begin
            $display("\\n✅✅✅ ALL TESTS PASSED! ✅✅✅");
        end else begin
            $display("\\n⚠️  Some tests failed");
        end
        $display("========================================\\n");

        $finish;
    end

endmodule
'''

    with open(output_file, 'w') as f:
        f.write(testbench_header)
        f.write(test_body)
        f.write(testbench_footer)


def main():
    """主函数"""
    print("🔧 Auto-Generating Verilog Testbenches")
    print("=" * 60)

    # 读取测试向量
    with open('test_vectors.json', 'r') as f:
        test_data = json.load(f)

    # 合并所有测试
    all_tests = (test_data['basic'] + test_data['boundary'] + test_data['extreme'] +
                test_data['sparse'] + test_data['pattern'] + test_data['random'][:5])

    print(f"\n📊 生成 {len(all_tests)} 个测试用例的testbench...")

    # 生成WS testbench
    print("\n📝 生成WS testbench...")
    generate_ws_testbench(all_tests, 'ws/tb/systolic_array_ws_auto_tb.v')
    print("  ✅ ws/tb/systolic_array_ws_auto_tb.v")

    # 生成IS testbench
    print("\n📝 生成IS testbench...")
    generate_is_testbench(all_tests, 'is/tb/systolic_array_is_auto_tb.v')
    print("  ✅ is/tb/systolic_array_is_auto_tb.v")

    # 生成OS testbench
    print("\n📝 生成OS testbench...")
    generate_os_testbench(all_tests, 'os/tb/systolic_array_os_auto_tb.v')
    print("  ✅ os/tb/systolic_array_os_auto_tb.v")

    print("\n" + "=" * 60)
    print("✅ Testbench生成完成！")
    print("\n运行方式:")
    print("  cd ws/tb && iverilog -g2012 -o sim ../../ws/src/*.v systolic_array_ws_auto_tb.v && vvp sim")
    print("  cd is/tb && iverilog -g2012 -o sim ../../is/src/*.v systolic_array_is_auto_tb.v && vvp sim")
    print("  cd os/tb && iverilog -g2012 -o sim ../../os/src/*.v systolic_array_os_auto_tb.v && vvp sim")


if __name__ == '__main__':
    main()
